// @@MODULE app-01-core — Состояние, хранилище, шифрование, облачная синхронизация, помощники, API
// logic-app.js — вся логика приложения (функции, обработчики, состояние).
// Загружается ПОСЛЕДНИМ, после всех data-*.js файлов, от которых зависит.

// build 5.76: доступность — у иконок-кнопок (🔒 🌐 🔍 ⚙️ 🔊 📤 ← → и т.д.)
// почти везде уже есть title (всплывающая подсказка), но title не всегда
// озвучивается скринридерами так же надёжно, как aria-label, а переписывать
// вручную тысячи мест генерации кнопок по всему файлу нереально. Вместо
// этого — один мост: копируем title → aria-label везде, где aria-label ещё
// нет, и переприменяем при каждом изменении DOM (почти весь интерфейс
// рисуется через innerHTML). MutationObserver раз в 300мс, не чаще — чтобы
// не грузить браузер на разделах с частыми перерисовками (чат, тесты).
function _applyAriaLabelsFromTitles(root) {
  (root || document).querySelectorAll('button[title]:not([aria-label])').forEach(function(b) {
    var t = b.getAttribute('title');
    if (t) b.setAttribute('aria-label', t);
  });
}
_applyAriaLabelsFromTitles();
(function() {
  var pending = false;
  try {
    var _ariaObserver = new MutationObserver(function() {
      if (pending) return;
      pending = true;
      setTimeout(function() { pending = false; _applyAriaLabelsFromTitles(); }, 300);
    });
    _ariaObserver.observe(document.body, { childList: true, subtree: true });
  } catch(e) {}
})();

    // ========== STATE & STORAGE ==========
    const STORAGE_KEY = 'quran-study-v1';

    /** Размер страницы списков (обновления, упомянутые хадисы…). 0 = без страниц. */
    function getListPageSize() {
      try {
        var n = (state.settings && state.settings.listPageSize);
        if (n === 0 || n === '0') return 0;
        n = parseInt(n, 10);
        if (n === 25 || n === 50 || n === 100 || n === 200) return n;
      } catch (e) {}
      return 25;
    }


    function formatDateRu(v) {
      try {
        const d = (v instanceof Date) ? v : new Date(v);
        if (isNaN(d.getTime())) return String(v || '');
        const dd = String(d.getDate()).padStart(2,'0');
        const mm = String(d.getMonth()+1).padStart(2,'0');
        const yyyy = d.getFullYear();
        return dd + '.' + mm + '.' + yyyy;
      } catch(e) { return String(v || ''); }
    }
    function formatDateTimeRu(v) {
      try {
        const d = (v instanceof Date) ? v : new Date(v);
        if (isNaN(d.getTime())) return String(v || '');
        const t = String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0');
        return formatDateRu(d) + ' ' + t;
      } catch(e) { return String(v || ''); }
    }


    // ========== ENCRYPTION LAYER (пароль + AES-GCM) ==========
    const SALT_KEY = 'quran_sec_salt_v1';
    const CHECK_KEY = 'quran_sec_check_v1';
    let cryptoKey = null; // держим только в памяти, никогда не сохраняем

    function bufToB64(buf) {
      const bytes = new Uint8Array(buf);
      let bin = '';
      for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
      return btoa(bin);
    }
    function b64ToBuf(b64) {
      const bin = atob(b64);
      const arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      return arr.buffer;
    }
    async function deriveKey(password, saltBuf) {
      const enc = new TextEncoder();
      const material = await crypto.subtle.importKey('raw', enc.encode(password), { name: 'PBKDF2' }, false, ['deriveKey']);
      return crypto.subtle.deriveKey(
        { name: 'PBKDF2', salt: saltBuf, iterations: 150000, hash: 'SHA-256' },
        material,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
      );
    }
    async function encryptString(key, plaintext) {
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const enc = new TextEncoder().encode(plaintext);
      const cipher = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc);
      return { iv: bufToB64(iv), data: bufToB64(cipher) };
    }
    async function decryptString(key, payload) {
      const iv = new Uint8Array(b64ToBuf(payload.iv));
      const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, b64ToBuf(payload.data));
      return new TextDecoder().decode(plainBuf);
    }
    function encryptAndStore(json) {
      // fire-and-forget
      try {
        if (!isAppLockEnabled()) {
          const data = JSON.parse(json);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ plain: true, data: data }));
          return;
        }
      } catch(e) {}
      if (!cryptoKey) return;
      encryptString(cryptoKey, json).then(payload => {
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(payload)); } catch (e) { console.warn('encryptAndStore', e); }
      }).catch(e => console.warn('encryptAndStore', e));
    }
    async function decryptMainBlob(key) {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return null;
      try {
        const payload = JSON.parse(raw);
        return await decryptString(key, payload);
      } catch (e) {
        console.warn('decryptMainBlob', e);
        return null;
      }
    }


    function getLastAudioPos() {
      let la = null;
      try {
        if (typeof state !== 'undefined' && state.lastAudio && state.lastAudio.surah) la = state.lastAudio;
      } catch(e) {}
      if (!la) {
        try { la = JSON.parse(localStorage.getItem('quran_last_audio_v1') || 'null'); } catch(e) {}
      }
      if (!la) la = { surah: 1, ayah: 1, title: 'Сура 1 · аят 1' };
      return { s: +(la.surah || 1), a: +(la.ayah || 1), la: la };
    }
    function ayahCountSafe(s) {
      try { if (typeof surahAyahCount === 'function') { const n = surahAyahCount(s); if (n) return n; } } catch(e) {}
      const FALLBACK = [0,7,286,200,176,120,165,206,75,129,109,123,111,43,52,99,128,111,110,98,135,112,78,118,64,77,227,93,88,69,60,34,30,73,54,45,83,182,88,75,85,54,53,89,59,37,35,38,29,18,45,60,49,62,55,78,96,29,22,24,13,14,11,11,18,12,12,30,52,52,44,28,28,20,56,40,31,50,40,46,42,29,19,36,25,22,17,19,26,30,20,15,21,11,8,8,19,5,8,8,11,11,8,3,9,5,4,7,3,3,3,5,4,5,6];
      return FALLBACK[s] || 1;
    }
    function updateLockPlayerLabels() {
      const p = getLastAudioPos();
      const t = document.getElementById('lock-lp-title');
      if (t) t.innerHTML = '🎧 Сура ' + p.s + ' · аят ' + p.a;
      const aud = document.getElementById('audio-player');
      const btn = document.getElementById('lock-play');
      if (btn) btn.textContent = (aud && !aud.paused && aud.src) ? '⏸' : '▶';
    }
    function renderLockPlayer() {
      const slot = document.getElementById('lock-player-slot');
      if (!slot) return;
      // Стабильный DOM — не мигает при смене аята
      if (!slot.querySelector('.lock-player')) {
        slot.innerHTML =
          '<div class="lock-player">' +
          '<div class="lp-title" id="lock-lp-title"></div>' +
          '<div class="lp-controls">' +
          '<button type="button" id="lock-surah-prev" title="Пред. сура">⏮⏮</button>' +
          '<button type="button" id="lock-ayah-prev" title="Пред. аят">⏮</button>' +
          '<button type="button" class="primary" id="lock-play" title="Пауза/плей">▶</button>' +
          '<button type="button" id="lock-ayah-next" title="След. аят">⏭</button>' +
          '<button type="button" id="lock-surah-next" title="След. сура">⏭⏭</button>' +
          '</div>' +
          '<div style="font-size:0.7rem;color:var(--text-muted);margin-top:0.35rem">крайние — суры · ближние — аяты</div>' +
          '</div>';
        const persist = (ns, na) => {
          const obj = { surah: ns, ayah: na, title: 'Сура ' + ns + ' · аят ' + na, url: (typeof ayahAudioUrl==='function'?ayahAudioUrl(ns,na):''), ts: Date.now() };
          try { state.lastAudio = obj; } catch(e) {}
          try { localStorage.setItem('quran_last_audio_v1', JSON.stringify(obj)); } catch(e) {}
        };
        const go = async (ns, na) => {
          persist(ns, na);
          updateLockPlayerLabels();
          try {
            if (typeof ensureSurahQueueAround === 'function') {
              const ok = await ensureSurahQueueAround(ns, na);
              if (ok && typeof playQueueItem === 'function') {
                if (typeof getRepeatCount === 'function') audioRepeatTotal = getRepeatCount();
                playQueueItem(audioQueueIdx);
              } else if (typeof ayahAudioUrl === 'function' && typeof playAudio === 'function') {
                playAudio(ayahAudioUrl(ns, na), 'Сура ' + ns + ' · аят ' + na, { surah: ns, ayah: na });
              }
            }
          } catch(e) {}
          setTimeout(updateLockPlayerLabels, 250);
        };
        document.getElementById('lock-surah-prev')?.addEventListener('click', (e) => {
          e.preventDefault(); e.stopPropagation();
          const p = getLastAudioPos();
          if (p.s <= 1) return;
          go(p.s - 1, 1);
        });
        document.getElementById('lock-surah-next')?.addEventListener('click', (e) => {
          e.preventDefault(); e.stopPropagation();
          const p = getLastAudioPos();
          if (p.s >= 114) return;
          go(p.s + 1, 1);
        });
        document.getElementById('lock-ayah-prev')?.addEventListener('click', (e) => {
          e.preventDefault(); e.stopPropagation();
          const p = getLastAudioPos();
          if (p.a > 1) go(p.s, p.a - 1);
          else if (p.s > 1) go(p.s - 1, ayahCountSafe(p.s - 1));
        });
        document.getElementById('lock-ayah-next')?.addEventListener('click', (e) => {
          e.preventDefault(); e.stopPropagation();
          const p = getLastAudioPos();
          const maxA = ayahCountSafe(p.s);
          if (p.a < maxA) go(p.s, p.a + 1);
          else if (p.s < 114) go(p.s + 1, 1);
        });
        document.getElementById('lock-play')?.addEventListener('click', async (e) => {
          e.preventDefault(); e.stopPropagation();
          const aud = document.getElementById('audio-player');
          if (aud && !aud.paused && aud.src) { aud.pause(); updateLockPlayerLabels(); return; }
          const p = getLastAudioPos();
          await go(p.s, p.a);
        });
      }
      updateLockPlayerLabels();
    }

    function lockScreenSetupUI(err) {
      const box = document.getElementById('lock-box');
      box.innerHTML =
        '<div class="lock-icon">🔐</div>' +
        '<h2>Создайте пароль</h2>' +
        '<p class="lock-sub">Все ваши заметки, закладки и прогресс будут зашифрованы этим паролем прямо на устройстве. Никто, включая нас, не сможет их прочитать без пароля.</p>' +
        '<input type="password" id="lock-pass1" placeholder="Придумайте пароль" autocomplete="new-password">' +
        '<input type="password" id="lock-pass2" placeholder="Повторите пароль" autocomplete="new-password">' +
        '<button type="button" class="lock-submit" id="lock-setup-btn">Создать и продолжить</button>' +
        '<div class="lock-error">' + (err || '') + '</div>';
      try { wrapPasswordEye('lock-pass1'); wrapPasswordEye('lock-pass2'); } catch(e) {}
      document.getElementById('lock-setup-btn').addEventListener('click', async () => {
        const p1 = document.getElementById('lock-pass1').value;
        const p2 = document.getElementById('lock-pass2').value;
        const errEl = box.querySelector('.lock-error');
        if (!p1 || p1.length < 4) { errEl.textContent = 'Минимум 4 символа.'; return; }
        if (p1 !== p2) { errEl.textContent = 'Пароли не совпадают.'; return; }
        errEl.textContent = 'Шифруем…';
        try {
          const salt = crypto.getRandomValues(new Uint8Array(16));
          const key = await deriveKey(p1, salt);
          const check = await encryptString(key, 'quran-lock-check');
          localStorage.setItem(SALT_KEY, bufToB64(salt));
          localStorage.setItem(CHECK_KEY, JSON.stringify(check));
          cryptoKey = key;
          try { localStorage.setItem('quran_app_lock_v1', '1'); } catch(e) {}
          document.getElementById('lock-screen').classList.add('hidden'); try{document.body.classList.remove('app-locked');}catch(e){};
          loadState(null);
          startApp();
        } catch (e) {
          console.error(e);
          errEl.textContent = 'Ошибка шифрования. Попробуйте ещё раз.';
        }
      });
    }

    function lockScreenUnlockUI() {
      const box = document.getElementById('lock-box');
      try { document.body.classList.add('app-locked'); } catch(e) {}
      try {
        var bar = document.getElementById('audio-bar');
        if (bar) { bar.classList.remove('visible'); bar.style.display = 'none'; }
      } catch(e) {}
      box.innerHTML =
        '<div class="lock-icon">🔒</div>' +
        '<h2>Приложение заблокировано</h2>' +
        '<p class="lock-sub">Введите пароль, чтобы расшифровать ваши данные.</p>' +
        '<input type="password" id="lock-pass" placeholder="Пароль" autocomplete="current-password">' +
        '<button type="button" class="lock-submit" id="lock-unlock-btn">Разблокировать</button>' +
        '<div class="lock-error"></div>' +
        '<div id="lock-player-slot" style="display:none"></div>' +
        '<div style="margin-top:0.75rem;font-size:0.8rem;line-height:1.45;opacity:0.85">' +
        '<button type="button" class="lock-reset-link" id="lock-reset-btn" style="display:block;margin:0.35rem auto">Забыли пароль приложения — стереть локальные данные</button>' +
        '<div style="font-size:0.72rem;opacity:0.75;margin-top:0.25rem">Это не аккаунт сайта. Сброс удалит данные только на этом устройстве.</div></div>';
      try { wrapPasswordEye('lock-pass'); } catch(e) {}
      try { document.getElementById('lock-pass')?.focus(); } catch(e) {}
      const submit = async () => {
        const pass = document.getElementById('lock-pass').value;
        const errEl = box.querySelector('.lock-error');
        // Уже разблокировано в этой сессии (мягкая блокировка) — просто закрыть оверлей
        if (cryptoKey && typeof startApp === 'function' && document.getElementById('view-home')) {
          // если пароль пустой или верный — скрыть; если введён — проверить
          if (!pass) {
            document.getElementById('lock-screen').classList.add('hidden'); try{document.body.classList.remove('app-locked');}catch(e){};
            try {
              var v = null;
              try { v = sessionStorage.getItem('quran_last_view'); } catch(e) {}
              if (!v) {
                try {
                  if (typeof viewStack !== 'undefined' && viewStack.length)
                    v = viewStack[viewStack.length-1];
                } catch(e) {}
              }
              if (!v || v === 'reader') v = 'dailyhub';
              if (typeof showView === 'function') showView(v, true);
              else if (typeof startApp === 'function') startApp();
            } catch(e) { try { startApp(); } catch(e2) {} }
            return;
          }
        }
        if (!pass) return;
        errEl.textContent = 'Проверяем…';
        try {
          const saltB64 = localStorage.getItem(SALT_KEY);
          const salt = b64ToBuf(saltB64);
          const key = await deriveKey(pass, salt);
          const check = JSON.parse(localStorage.getItem(CHECK_KEY));
          const plain = await decryptString(key, check);
          if (plain !== 'quran-lock-check') throw new Error('mismatch');
          cryptoKey = key;
          // если приложение уже запущено — только снять оверлей
          if (document.getElementById('view-home') || document.getElementById('view-dailyhub')) {
            document.getElementById('lock-screen').classList.add('hidden'); try{document.body.classList.remove('app-locked');}catch(e){};
            try {
              var v = null;
              try { v = sessionStorage.getItem('quran_last_view'); } catch(e) {}
              if (!v) {
                try {
                  if (typeof viewStack !== 'undefined' && viewStack.length)
                    v = viewStack[viewStack.length-1];
                } catch(e) {}
              }
              if (!v || v === 'reader') v = 'dailyhub';
              if (typeof showView === 'function') showView(v, true);
              else if (typeof startApp === 'function') startApp();
            } catch(e) { try { startApp(); } catch(e2) {} }
            return;
          }
          const raw = await decryptMainBlob(key);
          document.getElementById('lock-screen').classList.add('hidden'); try{document.body.classList.remove('app-locked');}catch(e){};
          loadState(raw);
          startApp();
        } catch (e) {
          errEl.textContent = 'Неверный пароль.';
        }
      };
      document.getElementById('lock-unlock-btn').addEventListener('click', submit);
      document.getElementById('lock-pass').addEventListener('keydown', e => { if (e.key === 'Enter') submit(); });
      document.getElementById('lock-reset-btn').addEventListener('click', () => {
        if (confirm('Это навсегда удалит все локальные данные приложения (заметки, закладки, прогресс) на этом устройстве, так как их нельзя расшифровать без старого пароля. Продолжить?')) {
          localStorage.removeItem(STORAGE_KEY);
          localStorage.removeItem(SALT_KEY);
          localStorage.removeItem(CHECK_KEY);
          location.reload();
        }
      });
    }

    function isAppLockEnabled() {
      try {
        const f = localStorage.getItem('quran_app_lock_v1');
        if (f === '1') return true;
        if (f === '0') return false;
      } catch(e) {}
      // По умолчанию ВЫКЛ. Вкл. только в настройках (или если уже задан пароль + флаг)
      return false;
    }

    function tryLoadPlainState() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return false;
        const parsed = JSON.parse(raw);
        if (parsed && parsed.plain && parsed.data) {
          loadState(JSON.stringify(parsed.data));
          return true;
        }
        // legacy unencrypted object (no iv/data)
        if (parsed && parsed.settings && !parsed.iv && !parsed.data) {
          loadState(raw);
          return true;
        }
      } catch(e) {}
      return false;
    }

    function initLockScreen() {
      document.getElementById('btn-lock-app')?.addEventListener('click', () => {
        if (!isAppLockEnabled()) {
          toast('Пароль при входе выключен в настройках');
          return;
        }
        try {
          if (state.lastAudio) localStorage.setItem('quran_last_audio_v1', JSON.stringify(state.lastAudio));
        } catch(e) {}
        try {
          var cur = (typeof viewStack !== 'undefined' && viewStack.length) ? viewStack[viewStack.length-1] : null;
          if (cur) {
            sessionStorage.setItem('quran_last_view', cur);
            localStorage.setItem('quran_last_view_persist', cur);
          }
        } catch(e) {}
        try { document.body.classList.add('app-locked'); } catch(e) {}
        try {
          var bar = document.getElementById('audio-bar');
          if (bar) { bar.classList.remove('visible'); bar.style.display = 'none'; }
        } catch(e) {}
        const lock = document.getElementById('lock-screen');
        if (lock) lock.classList.remove('hidden');
        lockScreenUnlockUI();
        // плеер на экране блокировки не показываем
      });

      // App lock disabled → skip password UI
      if (!isAppLockEnabled()) {
        const lock = document.getElementById('lock-screen');
        if (lock) lock.classList.add('hidden');
        if (!tryLoadPlainState()) {
          // try decrypt path unavailable without password; start fresh or empty
          try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
              const p = JSON.parse(raw);
              if (p && p.iv && p.data) {
                // still encrypted — must unlock once
                lockScreenUnlockUI();
                if (lock) lock.classList.remove('hidden');
                toast('Данные зашифрованы — введите пароль один раз');
                return;
              }
            }
          } catch(e) {}
          loadState(null);
        }
        startApp();
        return;
      }

      const hasSalt = !!localStorage.getItem(SALT_KEY);
      if (hasSalt) lockScreenUnlockUI(); else lockScreenSetupUI();
    }
    


