async function fetchTafsir(surah, ayah) {
      const edition = state.settings.tafsir || 'ru-tafseer-al-saddi';
      const key = edition + ':' + surah + ':' + ayah;
      if (!state.tafsirCache) state.tafsirCache = {};
      if (state.tafsirCache[key]) return state.tafsirCache[key];

      // build 5.17: кэш переведён на v2, потому что ниже поправлен разбор
      // ответа API (см. комментарий у Array.isArray) — под старым ключом
      // v1 могли залипнуть неверные тексты, сохранённые до фикса, и без
      // смены ключа они продолжали бы отдаваться из кэша даже после
      // исправления кода.
      try {
        const raw = localStorage.getItem('quran-tafsir-cache-v2');
        const disk = raw ? JSON.parse(raw) : {};
        if (disk[key]) {
          state.tafsirCache[key] = disk[key];
          return disk[key];
        }
      } catch (e) {}

      if (!navigator.onLine) throw new Error('Тафсир недоступен офлайн');

      let text = '';
      let sourceLabel = '';
      const isRuOfficial = edition === 'ru-tafseer-al-saddi';

      if (isRuOfficial) {
        // Official Russian tafsir via spa5k CDN (as-Sa'di)
        const url = 'https://cdn.jsdelivr.net/gh/spa5k/tafsir_api@main/tafsir/' + edition + '/' + surah + '.json';
        const res = await fetch(url);
        if (!res.ok) throw new Error('Ошибка загрузки тафсира');
        const raw = await res.json();
        // build 5.17: реальный ответ этого API — объект вида {ayahs:[...]},
        // а не голый массив. Старая проверка Array.isArray(arr) была всегда
        // false для такого ответа, из-за чего тафсир либо не находился
        // вовсе, либо (при иной форме ответа для части сур) съезжал не на
        // тот аят/суру. Разбираем оба возможных варианта формата.
        const arr = Array.isArray(raw) ? raw
          : (raw && Array.isArray(raw.ayahs)) ? raw.ayahs
          : (raw && Array.isArray(raw.data)) ? raw.data
          : null;
        const item = arr ? arr.find(x => +x.ayah === +ayah && (x.surah == null || +x.surah === +surah)) : null;
        text = item && item.text ? item.text : 'Тафсир для этого аята не найден';
        sourceLabel = 'Тафсир ас-Саади (пер. Э. Кулиева)';
      } else {
        // Arabic from AlQuran.Cloud
        const res = await fetch(API + '/ayah/' + surah + ':' + ayah + '/' + edition);
        const json = await res.json();
        text = json.data && json.data.text ? json.data.text : 'Тафсир не найден';
        sourceLabel = edition === 'ar.muyassar' ? 'Аль-Муяссар (араб.)' : 'Тафсир (араб.)';
      }

      const payload = { text: text, source: sourceLabel, isArabic: !isRuOfficial };
      state.tafsirCache[key] = payload;
      try {
        const raw = localStorage.getItem('quran-tafsir-cache-v2');
        const disk = raw ? JSON.parse(raw) : {};
        disk[key] = payload;
        const keys = Object.keys(disk);
        if (keys.length > 250) {
          keys.slice(0, keys.length - 250).forEach(k => delete disk[k]);
        }
        localStorage.setItem('quran-tafsir-cache-v2', JSON.stringify(disk));
      } catch (e) {}
      return payload;
    }
