    // ========== SPEECH: letter pronunciation ==========
    // Pronounceable syllable for each letter (letter + fatha)


function speakLetter(ch, name) {
      if (ch && typeof ch === 'object') {
        name = ch.name || name || '';
        ch = ch.ch || '';
      }
      name = name || ch || '';
      if (!window.speechSynthesis) {
        toast((isKk() ? 'Дыбысталу қолжетімсіз. Әріп: «' : 'Озвучка недоступна. Буква: «') + name + '»');
        return;
      }
      try { window.speechSynthesis.cancel(); } catch(e) {}

      // Force voice list load (important on mobile Chrome/Samsung)
      let voices = window.speechSynthesis.getVoices() || [];
      if (!voices.length) {
        window.speechSynthesis.getVoices();
        voices = window.speechSynthesis.getVoices() || [];
      }

      const ruVoice = voices.find(v => /^ru(-|$)/i.test(v.lang))
        || voices.find(v => /russian/i.test(v.name));
      const arVoice = voices.find(v => /^ar(-|$)/i.test(v.lang))
        || voices.find(v => /arab/i.test(v.name));

      // Russian first — reliable on Russian phones
      const uRu = new SpeechSynthesisUtterance(name);
      uRu.lang = 'ru-RU';
      uRu.rate = 0.9;
      uRu.volume = 1;
      if (ruVoice) uRu.voice = ruVoice;

      const arName = (typeof LETTER_SOUND !== 'undefined' && LETTER_SOUND[ch]) ? LETTER_SOUND[ch] : ch;

      uRu.onend = function() {
        // Then Arabic letter name if possible
        if (arVoice || true) {
          const uAr = new SpeechSynthesisUtterance(arName);
          uAr.lang = arVoice ? (arVoice.lang || 'ar-SA') : 'ar-SA';
          uAr.rate = 0.7;
          uAr.volume = 1;
          if (arVoice) uAr.voice = arVoice;
          try { window.speechSynthesis.speak(uAr); } catch(e) {}
        }
      };
      uRu.onerror = function(ev) {
        toast('Буква «' + name + '»');
      };

      try {
        window.speechSynthesis.speak(uRu);
        // Some Android browsers need a "kick"
        if (window.speechSynthesis.paused) window.speechSynthesis.resume();
      } catch (e) {
        toast('Буква «' + name + '»');
      }
    }

    // preload voices early
    if (window.speechSynthesis) {
      const warm = function() { window.speechSynthesis.getVoices(); };
      warm();
      window.speechSynthesis.onvoiceschanged = warm;
      // unlock audio on first touch (mobile)
      document.addEventListener('touchstart', function unlock() {
        try {
          const u = new SpeechSynthesisUtterance(' ');
          u.volume = 0;
          window.speechSynthesis.speak(u);
          window.speechSynthesis.cancel();
        } catch(e) {}
        document.removeEventListener('touchstart', unlock);
      }, { once: true });
    }

    // ========== SPEECH RECOGNITION test (грубая голосовая проверка чтения) ==========
    function getSpeechRecognition() {
      const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!SR) return null;
      const r = new SR();
      r.lang = 'ar-SA';
      r.interimResults = false;
      r.maxAlternatives = 3;
      return r;
    }

    function startListenTest(expectedList, onResult) {
      const rec = getSpeechRecognition();
      if (!rec) {
        toast('Распознавание речи не поддерживается. Используйте Chrome.');
        return null;
      }
      rec.onresult = (ev) => {
        const said = [];
        for (let i = 0; i < ev.results[0].length; i++) {
          said.push(ev.results[0][i].transcript.trim());
        }
        onResult(said);
      };
      rec.onerror = () => toast('Не удалось распознать. Попробуйте ещё раз.');
      rec.start();
      return rec;
    }

    // Глубокая нормализация арабского текста для приблизительного сравнения:
    // убираем огласовки/танвин, унифицируем родственные буквы, оставляем только буквы.
    function normalizeAr(s) {
      return (s || '')
        .replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g, '')
        .replace(/[إأآٱ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي')
        .replace(/ؤ/g, 'و')
        .replace(/ئ/g, 'ي')
        .replace(/[^\u0621-\u064A ]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function levenshteinDist(a, b) {
      const m = a.length, n = b.length;
      if (!m) return n;
      if (!n) return m;
      const dp = new Array(n + 1);
      for (let j = 0; j <= n; j++) dp[j] = j;
      for (let i = 1; i <= m; i++) {
        let prev = dp[0];
        dp[0] = i;
        for (let j = 1; j <= n; j++) {
          const tmp = dp[j];
          dp[j] = Math.min(
            dp[j] + 1,
            dp[j - 1] + 1,
            prev + (a[i - 1] === b[j - 1] ? 0 : 1)
          );
          prev = tmp;
        }
      }
      return dp[n];
    }

    // 0..1 — приблизительная похожесть произнесённого текста на эталон.
    // Это грубая оценка (посимвольный Левенштейн после нормализации), а не
    // настоящая фонетическая проверка таджвида — озвучиваем это в UI.
    function arSimilarity(said, expected) {
      const a = normalizeAr(said);
      const b = normalizeAr(expected);
      if (!a || !b) return 0;
      const dist = levenshteinDist(a, b);
      const maxLen = Math.max(a.length, b.length);
      return maxLen ? Math.max(0, 1 - dist / maxLen) : 0;
    }

    function voiceCheckVerdict(pct, kk) {
      if (pct >= 80) return kk ? '✅ Жақсы сәйкес келеді' : '✅ Похоже, совпадает хорошо';
      if (pct >= 50) return kk ? '🟡 Ішінара сәйкес — айырмашылықты қараңыз' : '🟡 Частично совпадает — есть расхождения';
      return kk ? '🔴 Күшті айырмашылық — қайта, баяу оқып көріңіз' : '🔴 Сильно отличается — попробуйте ещё раз, медленнее';
    }


