    function markLessonDone(lessonId) {
      if (!state.academyProgress) state.academyProgress = {};
      state.academyProgress[lessonId] = { done: true, ts: Date.now() };
      saveState();
      toast('Урок отмечен ✓');
      try { checkAchievements(); } catch(e) {}
      try { renderAcademy(); } catch(e) {}
    }
    function isLessonDone(id) {
      return !!(state.academyProgress && state.academyProgress[id] && state.academyProgress[id].done);
    }
    function academyStats() {
      let total = 0, done = 0;
      (ACADEMY_PATH || []).forEach(m => (m.lessons || []).forEach(l => { total++; if (isLessonDone(l.id)) done++; }));
      return { total, done, pct: total ? Math.round(done * 100 / total) : 0, streak: 0 };
    }
    function isModuleUnlocked(mi) {
      if (state.settings && state.settings.academySequential === false) return true;
      if (mi <= 0) return true;
      const prev = ACADEMY_PATH[mi - 1];
      if (!prev || !prev.lessons) return true;
      return prev.lessons.every(l => isLessonDone(l.id));
    }
    function isLessonUnlocked(mi, li) {
      if (state.settings && state.settings.academySequential === false) return true;
      if (!isModuleUnlocked(mi)) return false;
      if (li <= 0) return true;
      const prev = ACADEMY_PATH[mi].lessons[li - 1];
      return isLessonDone(prev.id);
    }
    function runLessonQuiz(lessonId, onPass) {
      const qs = (typeof LESSON_QUIZZES !== 'undefined' && LESSON_QUIZZES[lessonId]) || [];
      if (!qs.length) { onPass(); return; }
      let qi = 0, score = 0;
      const area = document.createElement('div');
      area.className = 'card';
      area.style.marginTop = '0.75rem';
      const paint = () => {
        if (qi >= qs.length) {
          const ok = score >= Math.ceil(qs.length * 0.67);
          area.innerHTML = '<div class="quiz-score">'+score+' / '+qs.length+'</div>' +
            '<p style="text-align:center;color:var(--text-muted)">'+(ok ? 'Отлично! Можно отметить урок.' : 'Нужно ≥ ⅔ правильных. Попробуйте ещё.')+'</p>' +
            (ok ? '<button type="button" class="btn btn-primary" style="width:100%" id="quiz-pass">Отметить выученным</button>' :
              '<button type="button" class="btn" style="width:100%" id="quiz-retry">Ещё раз</button>');
          area.querySelector('#quiz-pass')?.addEventListener('click', () => onPass());
          area.querySelector('#quiz-retry')?.addEventListener('click', () => { qi = 0; score = 0; paint(); });
          return;
        }
        const q = qs[qi];
        area.innerHTML = '<div class="quiz-q">Вопрос '+(qi+1)+'/'+qs.length+'<br>'+q.q+'</div><div class="quiz-opts"></div>';
        const opts = area.querySelector('.quiz-opts');
        q.opts.forEach((opt, oi) => {
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'acad-quiz-opt';
          b.textContent = opt;
          b.style.cssText = 'text-align:left;padding:0.75rem 1rem;background:var(--bg);border:1px solid var(--border);border-radius:0.6rem;color:var(--text);font-size:0.95rem;cursor:pointer;width:100%;margin-bottom:0.4rem';
          b.addEventListener('click', () => {
            opts.querySelectorAll('button').forEach(x => x.disabled = true);
            if (oi === q.a) { b.classList.add('correct'); score++; }
            else {
              b.classList.add('wrong');
              if (opts.children[q.a]) opts.children[q.a].classList.add('correct');
            }
            setTimeout(() => { qi++; paint(); }, 650);
          });
          opts.appendChild(b);
        });
      };
      paint();
      return area;
    }


