    function applyArabicSizeEverywhere(v) {
      try {
        if (!state.settings) state.settings = {};
        var n = parseFloat(v);
        if (!(n > 0)) n = 1.55;
        state.settings.arabicSize = n;
        state.settings.fontScaleAr = Math.round((n / 1.55) * 1000) / 1000;
        var s = document.getElementById('setting-arabic-size'); if (s) s.value = String(n);
        document.documentElement.style.setProperty('--arabic-size', n + 'rem');
        document.documentElement.style.setProperty('--ar-scale', String(state.settings.fontScaleAr));
        // Размер везде идёт только через --ar-scale (см. applySettings) —
        // никакого инлайнового font-size на элементы, иначе размер
        // «замораживается» только у элементов, которые были на экране
        // в момент нажатия, и не переносится в разделы, которые ещё не
        // открывались (отсюда и был баг с несимметричным сохранением).
        var prev = document.getElementById('arabic-size-preview'); if (prev) prev.style.fontSize = n + 'rem';
        var prevH = document.getElementById('fontsize-picker-preview-ar'); if (prevH) prevH.style.fontSize = n + 'rem';
        saveState();
        try { syncSettingPicks(); } catch (e2) {}
      } catch (e) {}
    }
    function applyTrSizeEverywhere(v) {
      try {
        if (!state.settings) state.settings = {};
        var n = parseFloat(v);
        if (!(n > 0)) n = 0.95;
        state.settings.trSize = n;
        state.settings.fontScaleRu = Math.round((n / 0.95) * 1000) / 1000;
        var s = document.getElementById('setting-tr-size'); if (s) s.value = String(n);
        document.documentElement.style.setProperty('--ru-scale', String(state.settings.fontScaleRu));
        // См. комментарий в applyArabicSizeEverywhere — размер только через
        // CSS-переменную --ru-scale, без инлайновой простановки на элементы.
        var prevH = document.getElementById('fontsize-picker-preview-tr'); if (prevH) prevH.style.fontSize = n + 'rem';
        saveState();
        try { syncSettingPicks(); } catch (e2) {}
      } catch (e) {}
    }
    function applyHeaderFontSize(v) { applyArabicSizeEverywhere(v); }
    function renderFontsizePickerList() {
      var curAr = String((state.settings && state.settings.arabicSize) || 1.55);
      var curTr = String((state.settings && state.settings.trSize) || 0.95);
      var listAr = document.getElementById('fontsize-picker-list-ar');
      var listTr = document.getElementById('fontsize-picker-list-tr');
      if (listAr) {
        listAr.innerHTML = FONTSIZE_LIST_AR.map(function(f) {
          return '<button type="button" class="size-pick-item' + (f.v === curAr ? ' active' : '') + '" data-v="' + f.v + '"><div class="arabic" dir="rtl" style="font-size:' + f.sample + 'rem">ب</div><div style="font-size:0.65rem">' + f.name + '</div></button>';
        }).join('');
        listAr.querySelectorAll('.size-pick-item').forEach(function(item) {
          item.addEventListener('click', function() {
            applyArabicSizeEverywhere(item.dataset.v);
            renderFontsizePickerList();
          });
        });
      }
      if (listTr) {
        listTr.innerHTML = FONTSIZE_LIST_TR.map(function(f) {
          return '<button type="button" class="size-pick-item' + (f.v === curTr ? ' active' : '') + '" data-v="' + f.v + '" style="font-size:' + f.sample + 'rem">Аят<div style="font-size:0.65rem">' + f.name + '</div></button>';
        }).join('');
        listTr.querySelectorAll('.size-pick-item').forEach(function(item) {
          item.addEventListener('click', function() {
            applyTrSizeEverywhere(item.dataset.v);
            renderFontsizePickerList();
          });
        });
      }
      var prevAr = document.getElementById('fontsize-picker-preview-ar');
      if (prevAr) prevAr.style.fontSize = curAr + 'rem';
      var prevTr = document.getElementById('fontsize-picker-preview-tr');
      if (prevTr) prevTr.style.fontSize = curTr + 'rem';
      // build 4.110: подпись на кнопке-переключателе — название ТЕКУЩЕГО
      // размера («показать одно»), список сворачивается сам сразу после
      // выбора — тот же приём, что и у выбора гарнитуры чуть ниже.
      var curArItem = FONTSIZE_LIST_AR.filter(function(f){ return f.v === curAr; })[0];
      var curTrItem = FONTSIZE_LIST_TR.filter(function(f){ return f.v === curTr; })[0];
      var labSizeAr = document.getElementById('label-fp-size-ar');
      if (labSizeAr) labSizeAr.textContent = (curArItem ? curArItem.name : 'Размер') + ' ▾';
      var labSizeTr = document.getElementById('label-fp-size-tr');
      if (labSizeTr) labSizeTr.textContent = (curTrItem ? curTrItem.name : 'Размер') + ' ▾';
      if (listAr) {
        listAr.querySelectorAll('.size-pick-item').forEach(function(item) {
          item.addEventListener('click', function() {
            listAr.classList.add('collapsed');
            var t = document.getElementById('toggle-fp-size-ar'); if (t) { var s = t.querySelector('span:last-child'); if (s) s.textContent = '▾'; }
          }, true); // capture — срабатывает раньше уже повешенного выше обработчика, но после re-render не мешает
        });
      }
      if (listTr) {
        listTr.querySelectorAll('.size-pick-item').forEach(function(item) {
          item.addEventListener('click', function() {
            listTr.classList.add('collapsed');
            var t = document.getElementById('toggle-fp-size-tr'); if (t) { var s = t.querySelector('span:last-child'); if (s) s.textContent = '▾'; }
          }, true);
        });
      }
    }
    function _bindFpSizeToggle(btnId, listId) {
      var btn = document.getElementById(btnId);
      var list = document.getElementById(listId);
      if (!btn || !list || btn._boundToggle) return;
      btn._boundToggle = true;
      btn.addEventListener('click', function() {
        list.classList.toggle('collapsed');
        var s = btn.querySelector('span:last-child');
        if (s) s.textContent = list.classList.contains('collapsed') ? '▾' : '▴';
      });
    }
    _bindFpSizeToggle('toggle-fp-size-ar', 'fontsize-picker-list-ar');
    _bindFpSizeToggle('toggle-fp-size-tr', 'fontsize-picker-list-tr');
    // build 4.110: выбор гарнитуры шрифта — тот же bindFontToggle, что и
    // в Настройках, только с другими id (свои копии элементов именно в
    // этом всплывающем окне быстрого доступа шапки — чтобы не задваивать
    // одни и те же id на странице).
    bindFontToggle('toggle-fp-family-ar', 'pick-fp-family-ar', 'label-fp-family-ar', function(){ return (state.settings && state.settings.arabicFont) || 'Amiri'; });
    bindFontToggle('toggle-fp-family-tr', 'pick-fp-family-tr', 'label-fp-family-tr', function(){
      var v = (state.settings && state.settings.trFont) || 'Inter';
      return (v.split(',')[0] || v).replace(/'/g,'');
    });
    document.getElementById('pick-fp-family-ar')?.querySelectorAll('[data-v]').forEach(function(item) {
      item.addEventListener('click', function() {
        state.settings.arabicFont = item.dataset.v;
        saveState(); applySettings();
        try { syncSettingPicks(); } catch(e) {}
        var sel = document.getElementById('setting-arabic-font'); if (sel) sel.value = item.dataset.v;
      });
    });
    document.getElementById('pick-fp-family-tr')?.querySelectorAll('[data-v]').forEach(function(item) {
      item.addEventListener('click', function() {
        state.settings.trFont = item.dataset.v;
        saveState(); applySettings();
        try { syncSettingPicks(); } catch(e) {}
        var sel = document.getElementById('setting-tr-font'); if (sel) sel.value = item.dataset.v;
      });
    });
    function applyFontsizePickerLang() {
      var kkFp = (typeof isKk === 'function') ? isKk() : (state.settings && state.settings.lang === 'kk');
      var fpTitle = document.getElementById('fontsize-picker-title');
      if (fpTitle) fpTitle.textContent = kkFp ? 'Aa Қаріп және өлшемдер' : 'Aa Шрифт и размеры';
      var fpClose = document.getElementById('fontsize-picker-close');
      if (fpClose) fpClose.textContent = kkFp ? 'Жабу' : 'Закрыть';
      var secTitles = document.querySelectorAll('#fontsize-picker-body .fp-section-title');
      var kkSec = ['Араб мәтінінің өлшемі, px (барлық жерде)', 'Араб қаріпінің гарнитурасы', 'Аударма өлшемі, px (барлық жерде)', 'Аударма гарнитурасы'];
      var ruSec = ['Размер арабского, px (везде)', 'Гарнитура арабского', 'Размер перевода, px (везде)', 'Гарнитура перевода'];
      secTitles.forEach(function(elx, i) { elx.textContent = kkFp ? (kkSec[i] || elx.textContent) : (ruSec[i] || elx.textContent); });
      var lblSizeAr = document.getElementById('label-fp-size-ar'); if (lblSizeAr) lblSizeAr.textContent = (kkFp ? 'Өлшем' : 'Размер') + ' ▾';
      var lblFamAr = document.getElementById('label-fp-family-ar'); if (lblFamAr) lblFamAr.textContent = (kkFp ? 'Қаріп таңдау' : 'Выбрать шрифт') + ' ▾';
      var lblSizeTr = document.getElementById('label-fp-size-tr'); if (lblSizeTr) lblSizeTr.textContent = (kkFp ? 'Өлшем' : 'Размер') + ' ▾';
      var lblFamTr = document.getElementById('label-fp-family-tr'); if (lblFamTr) lblFamTr.textContent = (kkFp ? 'Қаріп таңдау' : 'Выбрать шрифт') + ' ▾';
    }
