    // ========== Личный тафсир: журнал заметок к аятам ==========
    async function collectNotesJournal() {
      const notes = state.notes || {};
      const bySurah = {};
      Object.keys(notes).forEach(function(key) {
        const val = (notes[key] || '').trim();
        if (!val) return;
        const parts = key.split(':');
        const s = +parts[0], a = +parts[1];
        if (!s || !a) return;
        if (!bySurah[s]) bySurah[s] = [];
        bySurah[s].push({ ayah: a, note: val });
      });
      const surahNums = Object.keys(bySurah).map(Number).sort(function(a, b) { return a - b; });
      const journal = [];
      for (const s of surahNums) {
        let data = null;
        try { data = await fetchSurah(s); } catch (e) {}
        const items = bySurah[s].sort(function(a, b) { return a.ayah - b.ayah; });
        const ayahs = items.map(function(it) {
          const src = data && data.ayahs ? data.ayahs.find(function(x) { return +x.number === it.ayah; }) : null;
          return {
            num: it.ayah,
            text: (src && src.text) || '',
            translation: (src && src.translation) || '',
            note: it.note
          };
        });
        journal.push({
          surah: s,
          title: (typeof surahNameLocal === 'function') ? surahNameLocal(s) : ('Сура ' + s),
          ayahs: ayahs
        });
      }
      return journal;
    }

    function notesJournalToMarkdown(journal, kk) {
      const dateStr = new Date().toLocaleDateString(kk ? 'kk-KZ' : 'ru-RU');
      let md = '# ' + (kk ? 'Менің тәфсірім' : 'Мой тафсир') + '\n\n';
      md += (kk ? '_Жеке жазбалар жинағы · ' : '_Личный дневник изучения · ') + dateStr + '_\n\n---\n\n';
      journal.forEach(function(s) {
        md += '## ' + s.title + '\n\n';
        s.ayahs.forEach(function(a) {
          md += '**' + s.surah + ':' + a.num + '**\n\n';
          if (a.text) md += '> ' + a.text + '\n\n';
          if (a.translation) md += a.translation + '\n\n';
          md += (kk ? '📝 *Жазба:* ' : '📝 *Заметка:* ') + a.note + '\n\n';
        });
        md += '---\n\n';
      });
      return md;
    }

    function notesJournalToPrintHtml(journal, kk) {
      const dateStr = new Date().toLocaleDateString(kk ? 'kk-KZ' : 'ru-RU');
      const title = kk ? 'Менің тәфсірім' : 'Мой тафсир';
      const subtitle = (kk ? 'Жеке жазбалар жинағы · ' : 'Личный дневник изучения · ') + dateStr;
      const noteLabel = kk ? 'Жазба' : 'Заметка';
      let body = '';
      journal.forEach(function(s) {
        body += '<h2>' + s.title + '</h2>';
        s.ayahs.forEach(function(a) {
          body += '<div class="entry">' +
            '<div class="ref">' + s.surah + ':' + a.num + '</div>' +
            (a.text ? '<div class="arabic">' + a.text + '</div>' : '') +
            (a.translation ? '<div class="translation">' + a.translation + '</div>' : '') +
            '<div class="note"><b>📝 ' + noteLabel + ':</b> ' + a.note.replace(/</g, '&lt;') + '</div>' +
            '</div>';
        });
      });
      return '<!DOCTYPE html><html lang="' + (kk ? 'kk' : 'ru') + '"><head><meta charset="UTF-8">' +
        '<title>' + title + '</title>' +
        '<link href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Inter:wght@400;600;700&display=swap" rel="stylesheet">' +
        '<style>' +
        'body{font-family:Inter,system-ui,sans-serif;color:#1e293b;max-width:760px;margin:0 auto;padding:2rem 1.5rem;line-height:1.5}' +
        'h1{font-size:1.6rem;margin-bottom:0.15rem}' +
        '.subtitle{color:#64748b;font-size:0.9rem;margin-bottom:2rem}' +
        'h2{font-size:1.2rem;color:#059669;border-bottom:2px solid #d1fae5;padding-bottom:0.3rem;margin-top:2.2rem}' +
        '.entry{margin:1rem 0 1.5rem;page-break-inside:avoid}' +
        '.ref{font-weight:700;color:#059669;font-size:0.85rem;margin-bottom:0.3rem}' +
        '.arabic{font-family:"Amiri",serif;font-size:1.4rem;direction:rtl;text-align:right;line-height:2;color:#0f172a;margin-bottom:0.4rem}' +
        '.translation{color:#334155;margin-bottom:0.5rem}' +
        '.note{background:#f8fafc;border-left:3px solid #10b981;padding:0.6rem 0.8rem;border-radius:0.3rem;font-size:0.95rem}' +
        '@media print{body{padding:0}}' +
        '</style></head><body>' +
        '<h1>' + title + '</h1><div class="subtitle">' + subtitle + '</div>' +
        body +
        '</body></html>';
    }

    async function exportNotesMarkdown() {
      const kk = isKk();
      const journal = await collectNotesJournal();
      if (!journal.length) { toast(kk ? 'Жазбалар жоқ' : 'Заметок пока нет'); return; }
      const md = notesJournalToMarkdown(journal, kk);
      const blob = new Blob([md], { type: 'text/markdown;charset=utf-8' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'my-tafsir-' + new Date().toISOString().slice(0, 10) + '.md';
      a.click();
    }

    async function exportNotesPDF() {
      const kk = isKk();
      const journal = await collectNotesJournal();
      if (!journal.length) { toast(kk ? 'Жазбалар жоқ' : 'Заметок пока нет'); return; }
      const html = notesJournalToPrintHtml(journal, kk);
      const w = window.open('', '_blank');
      if (!w) { toast(kk ? 'Терезе бұғатталды — қалқымалы терезелерге рұқсат беріңіз' : 'Окно заблокировано — разрешите всплывающие окна'); return; }
      w.document.open();
      w.document.write(html);
      w.document.close();
      setTimeout(function() { try { w.print(); } catch (e) {} }, 400);
    }

