    // Quality Arabic TTS: try browser AR voice, then Google Translate TTS audio
    let _adhkarAudio = null;

    // Разбивает арабский текст на естественные куски (по концам предложений/пауз,
    // затем по словам), чтобы озвучка звучала связнее, а не обрывалась на полуслове.
    function splitArabicForSpeech(str, max) {
      str = String(str || '').trim();
      max = max || 170;
      if (!str) return [];
      // сначала режем по явным паузам: точка, запятая, ؟ ! · … двоеточие, вав-соединение после длинной фразы
      const rough = str.split(/(?<=[\.\!\؟\:\؛,،·])\s+/).filter(Boolean);
      const parts = [];
      let cur = '';
      rough.forEach(seg => {
        if ((cur + ' ' + seg).trim().length <= max) {
          cur = (cur ? cur + ' ' : '') + seg;
        } else {
          if (cur) parts.push(cur);
          if (seg.length <= max) cur = seg;
          else {
            // сегмент сам слишком длинный — режем по словам
            let rest = seg;
            while (rest.length > max) {
              let cut = rest.lastIndexOf(' ', max);
              if (cut < 30) cut = max;
              parts.push(rest.slice(0, cut).trim());
              rest = rest.slice(cut).trim();
            }
            cur = rest;
          }
        }
      });
      if (cur) parts.push(cur);
      return parts.filter(Boolean);
    }

