          var h0 = list0[q]; if (!h0 || !h0.ar || h0.ar === '…' || h0 === r0) continue;
          var same = (String(h0.num) === String(num) && (h0.book === r0.book)) || (h0.also || []).some(function (a) { return String(a.num) === String(num) && a.book === r0.book; });
