            if ((bn.indexOf('ibnmajah')>=0 || bn.indexOf('маджа')>=0 || bn.indexOf('мажа')>=0) && /маджа|majah/i.test(sl) && new RegExp('(?:маджа|majah)[^0-9]{0,12}'+n,'i').test(sl)) return h;
