    (function () {
      var v = document.getElementById('view-reader'), x0 = null, y0 = 0, t0 = 0;
      if (!v) return;
      v.addEventListener('touchstart', function (e) {
        if (!zenActive() || !e.touches || !e.touches[0]) return;
        x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; t0 = Date.now(); zenPoke();
      }, { passive: true });
      v.addEventListener('touchend', function (e) {
        if (x0 === null) return;
        var t = e.changedTouches && e.changedTouches[0], sx = x0; x0 = null;
        if (!t || !zenActive() || !document.body.classList.contains('zen-one')) return;
        var dx = t.clientX - sx, dy = t.clientY - y0;
        if (Date.now() - t0 > 700 || Math.abs(dx) < 50 || Math.abs(dx) < Math.abs(dy) * 1.4) return;
        zenShow(_zen.idx + (dx < 0 ? 1 : -1));
      }, { passive: true });
      v.addEventListener('mousemove', function () { if (zenActive()) zenPoke(); });
    })();
    document.addEventListener('keydown', function (e) {
      if (!zenActive()) return;
      if (e.key === 'Escape') { zenExit(); return; }
      if (!document.body.classList.contains('zen-one')) return;
      if (e.key === 'ArrowLeft') { zenShow(_zen.idx + 1); zenPoke(); }
      else if (e.key === 'ArrowRight') { zenShow(_zen.idx - 1); zenPoke(); }
    });
    document.addEventListener('visibilitychange', function () { if (!document.hidden && zenActive()) zenWake(); });
    document.addEventListener('fullscreenchange', function () { if (!document.fullscreenElement) _zen.fs = false; });

    document.getElementById('btn-loop-range')?.addEventListener('click', async () => {
      if (!state.currentSurah) return;
      const from = parseInt(document.getElementById('loop-from').value, 10);
      const to = parseInt(document.getElementById('loop-to').value, 10);
      if (!from || !to || from > to) { toast('Укажите диапазон, например 1–5'); return; }
      const data = await fetchSurah(state.currentSurah);
      const slice = data.ayahs.filter(a => a.number >= from && a.number <= to && a.audio);
      if (!slice.length) { toast('Нет аудио в диапазоне'); return; }
      // build looping queue by repeating range many times
      const loops = 20;
      let queue = [];
      for (let i = 0; i < loops; i++) {
        slice.forEach(a => queue.push({ url: a.audio, title: 'Сура '+state.currentSurah+', аят '+a.number }));
      }
      playAudio(queue[0].url, queue[0].title, { queue: queue, queueIdx: 0, repeat: 1 });
      toast('Цикл '+from+'–'+to+' (остановка — кнопка ■)');
    });

    // Media Session for background-ish controls
    function updateMediaSession(title) {
      if (!('mediaSession' in navigator)) return;
      try {
        var av = document.querySelector('.view.active');
        if (av && (av.id === 'view-learn' || av.id === 'view-games')) {
          try { navigator.mediaSession.metadata = null; } catch(e) {}
          return;
        }
        navigator.mediaSession.metadata = new MediaMetadata({
          title: title || 'Коран',
          artist: 'Изучение Корана',
          album: 'Quran Study'
        });
        navigator.mediaSession.setActionHandler('play', () => { document.getElementById('audio-player').play(); });
        navigator.mediaSession.setActionHandler('pause', () => { document.getElementById('audio-player').pause(); });
        navigator.mediaSession.setActionHandler('stop', () => {
          const a = document.getElementById('audio-player');
          a.pause(); a.src = '';
        });
      } catch (e) {}
    }



    // ========== SHORT LESSONS ==========


    function renderLessons() {
      const list = document.getElementById('lessons-list');
      const content = document.getElementById('lesson-content');
      if (!list) return;
      if (content) content.style.display = 'none';
      list.style.display = 'block';
      list.innerHTML = LESSONS.map(l =>
        '<div class="card" style="cursor:pointer" data-lesson="'+l.id+'">' +
        '<strong>'+l.title+'</strong>' +
        '<div class="surah-meta">'+l.time+'</div></div>'
      ).join('');
      list.querySelectorAll('[data-lesson]').forEach(el => {
        el.addEventListener('click', () => openLesson(el.dataset.lesson));
      });
    }

    function openLesson(id) {
      const l = LESSONS.find(x => x.id === id);
      if (!l) return;
      const list = document.getElementById('lessons-list');
      const content = document.getElementById('lesson-content');
      if (list) list.style.display = 'none';
      if (!content) return;
      content.style.display = 'block';
      content.innerHTML =
        '<button class="btn btn-sm" id="btn-lessons-back">← Все уроки</button>' +
        '<h3 style="margin:1rem 0 0.25rem;font-size:1.15rem">'+l.title+'</h3>' +
        '<div class="surah-meta" style="margin-bottom:1rem">'+l.time+'</div>' +
        l.body.map(p => '<div class="card" style="margin-bottom:0.5rem;line-height:1.55">'+p+'</div>').join('');
      document.getElementById('btn-lessons-back')?.addEventListener('click', renderLessons);
    }
