    // Hardware / browser back button
    (function setupHistoryBack() {
      let skip = false;
      const origShow = window.showView;
      // wrap after showView defined - call at init
      window.__quranSetupBack = function() {
        try {
          history.replaceState({ view: 'dailyhub' }, '');
        } catch(e) {}
        window.addEventListener('popstate', function(ev) {
          if (skip) return;
          if (typeof goBack === 'function' && viewStack && viewStack.length > 1) {
            goBack();
            try {
              skip = true;
              history.pushState({ view: viewStack[viewStack.length-1] }, '');
              skip = false;
            } catch(e) {}
          } else if (typeof goBack === 'function') {
            // один экран в стеке: goBack сам решит (Ещё → меню, иначе dailyhub)
            goBack();
            try {
              skip = true;
              history.pushState({ view: (viewStack && viewStack[viewStack.length-1]) || 'dailyhub' }, '');
              skip = false;
            } catch(e) {}
          } else if (typeof showView === 'function') {
            showView('dailyhub', true);
          }
        });
      };
    })();


